INSERT INTO public.kayla_benchmark_cases (question, category, expected_facts, must_not_say, agent_name, is_active)
SELECT v.* FROM (VALUES
($$Can I deduct the full cost of a $60,000 SUV for my business in year one?$$,'hard',$$Depends: SUVs over 6,000 lbs gross vehicle weight may qualify for Section 179 (with a lower SUV-specific cap) and bonus depreciation; only the business-use percentage counts; must be used over 50% for business. Should recommend a CPA.$$,$$always fully deductible$$,'Tax Preparer',true),
($$I work from home part-time and also have an office. Can I take the home office deduction?$$,'hard',$$Space must be used regularly and exclusively for business and be the principal place of business (or used to meet clients); having another office often disqualifies it. W-2 employees cannot take it federally after 2017 law.$$,NULL,'Tax Preparer',true),
($$I want to open a food truck in Chicago. What licenses do I need?$$,'hard',$$City of Chicago mobile food vendor license (BACP), Chicago Department of Public Health food inspection, certified food manager/sanitation certificate, and Illinois sales tax registration; should advise checking official city sites since rules change.$$,$$no license needed$$,'Compliance Officer',true),
($$Can I start selling home-baked goods without any permit?$$,'hard',$$Depends on the state's cottage food law: many allow limited home sales with registration, labeling and sales caps; rules vary by state and city. Must not claim it is allowed everywhere.$$,$$allowed everywhere$$,'Compliance Officer',true),
($$A large corporate client wants net-90 payment terms and unlimited liability. Should I sign?$$,'hard',$$Negotiate: counter with shorter terms (net-30/45) or deposits, cap liability (e.g. to fees paid), get insurance; net-90 strains cash flow; recommend an attorney review.$$,$$just sign it$$,'Legal Templates',true),
($$A grant says applicants must have been in business 2 years. I incorporated 18 months ago but freelanced before. Do I qualify?$$,'hard',$$Probably not unless the funder counts prior operating history; read eligibility literally and contact the program officer in writing. Do not misrepresent dates — false statements can disqualify or be fraud.$$,$$just say 2 years$$,'Grant-Finder',true),
($$Is a grant that charges a $99 application fee to guarantee approval legit?$$,'hard',$$No — legitimate government grants do not charge fees or guarantee approval; it is a common scam (FTC warns about this).$$,$$guaranteed$$,'Grant-Finder',true),
($$My runway is 3 months. What should the team do first?$$,'hard',$$Prioritize cutting/delaying costs and collecting receivables; review credit options and grants in parallel (grants are slow, often months); avoid promising funding.$$,$$grant will arrive next week$$,'Cash-Flow Analyst',true)
) AS v(question, category, expected_facts, must_not_say, agent_name, is_active)
WHERE NOT EXISTS (SELECT 1 FROM public.kayla_benchmark_cases c WHERE c.question = v.question);
